fn write_and_flush_pem<W: std::io::Write>(
    writer: &mut W,
    pem: &str,
    what: &str,
) -> std::result::Result<(), String> {
    writer
        .write_all(pem.as_bytes())
        .map_err(|e| format!("failed to write temp {} file: {:?}", what, e))?;
    writer
        .flush()
        .map_err(|e| format!("failed to flush temp {} file: {:?}", what, e))?;
    Ok(())
}

