        }
    }
}

fn histogram_to_snapshot(h: &LatencyHistogram) -> HistogramSnapshot {
    HistogramSnapshot {
        le: histogram::BUCKETS.to_vec(),
        cumulative_count: h
            .cumulative_counts()
            .iter()
            .map(|&c| c as f64)
            .collect::<Vec<_>>(),
        count: h.count() as f64,
        sum_secs: h.sum_secs(),
    }
}

fn js_sys_timestamp() -> f64 {
    #[cfg(not(target_arch = "wasm32"))]
