		const infBucketLabels = baseLabels
			? `{le="+Inf",${baseLabels}}`
			: `{le="+Inf"}`;
		lines.push(`${bn}_seconds_bucket${infBucketLabels} ${Math.round(count)}`);
		lines.push(`${bn}_seconds_count${metricLabels} ${Math.round(count)}`);
