  maxQueuedBytesGlobal: number;
  maxQueuedBytesPerSession: number;
  maxQueuedBytesPerStream: number;

  backpressureTimeoutMs: number;
  handshakeTimeoutMs: number;
  idleTimeoutMs: number;
};

