				const msg = err instanceof Error ? err.message : String(err);
				console.warn(`[webtransport] log callback failed: ${msg}`);
			}
		}
	};

	const logCallback = (logEvents: any[]) => {
		for (const le of logEvents) {
			emitUserLog({
				level: le.level ?? "info",
				msg: le.msg ?? "",
