function normalizeToBrowserName(
	code: ErrorCode,
	message: string,
): string | undefined {
	if (
		message.includes(
			"serverCertificateHashes cannot be used with allowPooling=true",
		)
	) {
		return "NotSupportedError";
	}
	if (message.includes("serverCertificateHashes must be an array")) {
