 */
export type WebTransportClientOptions = {
	/** When true, errors use browser-style DOMException names (NotSupportedError, etc.). Default false for backward compat. */
	strictW3CErrors?: boolean;
	serverCertificateHashes?: Array<{
		algorithm: "sha-256";
