pub(crate) fn build_live_resolver_from_pem(
    cert_pem: &str,
    key_pem: &str,
) -> std::result::Result<Arc<LiveServerCertResolver>, String> {
    let default_cert = parse_certified_key(cert_pem, key_pem)?;
